        static void Need(bool value,string message){if(!value)throw new Exception(message);}
        static int N(string value){return int.Parse(value,System.Globalization.CultureInfo.InvariantCulture);}
        static string Hash(byte[] bytes){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(bytes)).Replace("-","");}
        static string Digest(PracticeParticipantCompletionResult result){using(var stream=new MemoryStream()){using(var writer=new BinaryWriter(stream)){result.WriteOriginalPacket(writer);writer.Flush();return Hash(stream.ToArray());}}}
        static bool Reject(Action action){try{action();return false;}catch(ArgumentException){return true;}catch(InvalidDataException){return true;}catch(NotSupportedException){return true;}}
        internal static void Run(Action<string,Action> check,string assets)
        {
            check("Participant completion matches120original complete record/count/format/callback digests",delegate{
                Need(OriginalCases.Length==120,"Original participant extent");int requests=0,formations=0,oversubscribed=0;
                for(int id=0;id<OriginalCases.Length;id++)
                {
                    string[] p=OriginalCases[id].Split(',');Need(p.Length==7&&N(p[0])==id,"Original participant metadata");int mode=N(p[1]),target=N(p[2]),current=N(p[3]);byte pattern=checked((byte)N(p[4]));byte[] input=PracticeParticipantCompletion.CreateInspectionFixture(current,pattern);Need(Hash(input)==p[5],"Original declared before fixture");var result=PracticeParticipantCompletion.Complete(input,target,current,mode);Need(Digest(result)==p[6],"Complete original participant state "+id);requests+=result.NameRequests.Count;formations+=result.FormationRequests.Count;if(current>target)oversubscribed++;
                }
                Need(requests==120&&formations==40&&oversubscribed==36,"Original participant output totals");
            });
            check("One missing participant retains existing record and opaque inserted bytes",delegate{
                byte[] input=PracticeParticipantCompletion.CreateInspectionFixture(1,0xa7);string before=Hash(input);var result=PracticeParticipantCompletion.Complete(input,2,1,0);byte[] after=result.CopyRecords();
                Need(result.FinalCount==2&&result.KindAt(1)==2&&result.IdAt(1)==1&&result.DisplayNameAt(1)=="CPU"&&!result.NameRequests[0].Numbered&&result.NameRequests[0].SourceArgument==-1,"Single source name decision");
                for(int n=0;n<44;n++)Need(input[n]==after[n],"Existing participant prefix untouched");Need(after[44+14]==input[44+14]&&after[44+15]==input[44+15]&&BitConverter.ToInt16(after,44+12)==0,"Source WORD reset preserves adjacent opaque bytes");
                for(int slot=2;slot<4;slot++){Need(BitConverter.ToInt32(after,slot*44)==0,"Unused kind cleared");for(int n=4;n<44;n++)Need(after[slot*44+n]==input[slot*44+n],"Remaining unused record preserved");}Need(Hash(input)==before,"Caller records unchanged");
            });
            check("Multiple missing participants use one numbered-label decision and per-insert formation requests",delegate{
                byte[] input=PracticeParticipantCompletion.CreateInspectionFixture(1,0x6d);var result=PracticeParticipantCompletion.Complete(input,4,1,5);
                Need(result.FinalCount==4&&result.NameRequests.Count==3&&result.FormationRequests.Count==3,"Three appended source records");for(int n=0;n<3;n++)Need(result.NameRequests[n].Slot==n+1&&result.NameRequests[n].Numbered&&result.NameRequests[n].SourceArgument==n+1&&result.DisplayNameAt(n+1)=="CPU "+(n+1)&&result.FormationRequests[n]==n+1,"Original zero-based index and callback timing");
                Need(PracticeParticipantCompletion.Complete(input,4,1,0).FormationRequests.Count==0&&PracticeParticipantCompletion.Complete(input,4,1,20).FormationRequests.Count==0,"Source mode0/20 formation gate");
            });
            check("Participant oversubscription stays intact and result inspection returns independent copies",delegate{
                byte[] input=PracticeParticipantCompletion.CreateInspectionFixture(4,0xa7);var result=PracticeParticipantCompletion.Complete(input,2,4,5);
                Need(result.FinalCount==4&&!result.CanUseCompletedCounts&&result.NameRequests.Count==0&&result.FormationRequests.Count==0&&Hash(input)==Hash(result.CopyRecords()),"No invented truncation or completion callbacks");
                string before=Digest(result);var copy=result.CopyRecords();copy[0]^=1;var initial=result.CopyBeforeRecords();initial[0]^=1;Need(Digest(result)==before&&Hash(input)==Hash(result.CopyRecords()),"Inspection copies isolated");
            });
            check("Participant completion rejects unsupported bounds,modes and record extents",delegate{
                byte[] input=PracticeParticipantCompletion.CreateInspectionFixture(1,0x6d);Need(Reject(delegate{PracticeParticipantCompletion.Complete(new byte[175],2,1,0);})&&Reject(delegate{PracticeParticipantCompletion.Complete(input,0,1,0);})&&Reject(delegate{PracticeParticipantCompletion.Complete(input,5,1,0);})&&Reject(delegate{PracticeParticipantCompletion.Complete(input,2,5,0);})&&Reject(delegate{PracticeParticipantCompletion.Complete(input,2,1,1);}),"Explicit source profile bounds");Need(Reject(delegate{PracticeParticipantCompletion.CreateInspectionFixture(1,0);})&&Reject(delegate{PracticeParticipantCompletion.Complete(input,2,1,0).KindAt(4);}),"Fixture/inspection bounds");
            });
            check("Completed participant counts drive all configured bank5 groups without relabeling partial contexts",delegate{
                var tables=PracticeReinforcementTables.Load(Path.Combine(Path.GetDirectoryName(assets),"Programs"));
                for(int target=1;target<=4;target++)for(int current=0;current<=target;current++)
                {
                    var participants=PracticeParticipantCompletion.Complete(PracticeParticipantCompletion.CreateInspectionFixture(current,0x6d),target,current,5);Need(participants.CanUseCompletedCounts&&participants.FinalCount==target,"Completed source count");var waves=PracticeGeneratedReinforcements.Create(tables,target,participants.FinalCount,731,0,false,1).FinishInDeadlineOrder();Need(waves.CreatedFleetCount==target*4&&waves.CreatedUnitCount==target*20,"Explicit composition consumes every configured group");
                }
                var partial=PracticeGeneratedReinforcements.Create(tables,2,1,731,0,false,1).FinishInDeadlineOrder();Need(partial.CreatedFleetCount==4&&partial.DeadlineAt(1,0)!=-1,"Retained partial count fixture remains distinct");
            });
        }
